// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"zh-Hans","term":"市值（Market Cap）","aka":["Market Cap","流通市值","Market capitalization"],"short":"市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。","body":["只看单价无法判断一个币的大小。单价 0.01 美元的币如果流通了 1000 亿枚，市值就是 10 亿美元，比单价 100 美元、流通 100 万枚的币（市值 1 亿美元）大得多。所以行情网站通常按市值给币种排名。",["市值一般用",["流通量","circulating-supply"],"计算，所以也叫流通市值。如果用总供应量或最大供应量计算，得到的是",["完全稀释估值（FDV）","fully-diluted-valuation"],"。两者差距越大，说明未来还有越多代币可能进入市场。"],["市值不等于有人真的投入了这么多钱，也不代表能按这个价格全部卖出。小市值币如果",["交易量","trading-volume"],"低，少量资金就能把价格拉高或砸低，显示的市值会随之大幅变化。"]],"example":["假设代币 A 价格 2 ",["USDT","usdt"],"，流通量 5 亿枚，市值 = 2 × 5 亿 = 10 亿 USDT。代币 B 价格 0.05 USDT，流通量 400 亿枚，市值 = 0.05 × 400 亿 = 20 亿 USDT。虽然 B 单价只有 A 的四十分之一，市值却是 A 的 2 倍。B 要从 0.05 涨到 1 USDT，市值得达到 400 亿 USDT。"],"mistakes":["觉得单价低的币“便宜”，没有换算成市值来比较。","以为市值就是项目实际融到或沉淀的资金。","只看市值排名，不看交易量和流动性，低估了卖出难度。"],"faq":[{"q":"市值和 FDV 有什么区别？","a":"市值按当前流通量计算，FDV 按最大或总供应量计算。FDV 远高于市值时，意味着未来解锁的代币可能带来抛压。"},{"q":"市值越大越安全吗？","a":"市值大的币通常流动性更好、被操纵难度更高，但价格仍会大幅波动，并不等于没有风险。"}],"title":"什么是市值（Market Cap）？加密货币市值怎么算","description":"加密货币市值是怎么计算的？用例子讲清市值等于价格乘流通量，为什么单价低不代表便宜，以及市值和 FDV 的区别。","related":[["fully-diluted-valuation","完全稀释估值（FDV）","完全稀释估值（FDV）是用当前价格乘以代币最大供应量（或总供应量）算出的估值，表示所有代币都流通后的理论市值。"],["circulating-supply","流通量（Circulating Supply）","流通量是指当前已在市场上自由流通、可以被交易的代币数量，不包括仍处于锁仓或尚未发行的部分。"],["trading-volume","成交量（Trading Volume）","成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。"],["tokenomics","代币经济学（Tokenomics）","代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。"],["altcoin","山寨币（Altcoin）","山寨币是指比特币以外的所有加密货币，包括以太坊、Solana 等公链币，也包括各种应用代币和 Meme 币。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"zh-Hans","term":"做市商（Market Maker）","aka":["做市方","MM","market maker"],"short":"做市商是在订单簿上持续同时挂出买单和卖单、为市场提供流动性的交易者或机构，主要通过买卖价差和交易所的挂单返佣获利。","body":[["做市商通常用程序在当前价格上下两侧挂单，买得略低、卖得略高。别人随时想买或卖，都能找到对手盘，这让",["买卖价差","bid-ask-spread"],"变窄、深度变厚。",["交易所","centralized-exchange"],"为了吸引做市商，常给它们很低甚至为负的",["挂单费","maker-taker-fees"],"率。"],["做市商最大的风险是库存风险：如果行情单边下跌，它的买单不断成交，手里积累的币越来越多，价差赚的钱可能不够弥补跌价损失。所以做市商需要不停调整报价，并用合约",["对冲","hedging"],"库存。"],["项目方上新币时常会聘请做市商维持基本",["流动性","liquidity"],"，这本身是正常业务。但如果做市协议约定了拉盘、托价或",["刷量","wash-trading"],"，就可能变成市场操纵。去中心化交易所里的自动做市商（AMM）则用流动性池和公式代替人工报价。"]],"example":"假设 BTC 中间价 60,000 USDT，做市商在 59,990 挂买单、60,010 挂卖单，价差 20 USDT。如果一分钟内买单和卖单各成交 0.5 BTC，它在价差上赚 0.5 × 20 = 10 USDT，再加上可能的挂单返佣。可如果价格突然跌到 59,700，它在 59,990 买入的 0.5 BTC 就浮亏 145 USDT，远超刚才赚的价差。","mistakes":["以为做市商只是在“控盘”，忽略它为普通用户提供了可成交的对手盘。","把做市商撤单导致的深度骤减当成正常行情，在这时用大额市价单下单。","以为自己挂限价单就等同于做市，忽略做市需要双边报价和库存管理。"],"faq":[{"q":"做市商靠什么赚钱？","a":"主要靠低买高卖之间的价差，以及交易所给的挂单返佣。它承担的主要风险是行情单边移动带来的库存亏损。"},{"q":"做市商和自动做市商（AMM）有什么区别？","a":"做市商是在订单簿上主动报价的交易者；AMM 是去中心化交易所里的智能合约，按流动性池的公式自动给出价格，任何人都可以存入资金成为流动性提供者。"}],"title":"做市商是什么？加密货币 Market Maker 如何赚钱","description":"解释做市商（Market Maker）在订单簿上的作用、如何靠价差和返佣赚钱、承担哪些库存风险，以及与 AMM 的区别。","related":[["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["bid-ask-spread","买卖价差（Bid-Ask Spread）","买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。"],["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["amm","自动做市商（AMM）","自动做市商（AMM）是一种用流动性池和数学公式自动给代币定价的交易机制，不需要买卖双方挂单撮合，是 Uniswap 等去中心化交易所的核心。"]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"zh-Hans","term":"盈亏比（Risk-Reward Ratio）","aka":["风险回报比","收益风险比","RR"],"short":"盈亏比是一笔交易计划中可能亏损的金额与可能盈利的金额之比，例如止损亏 100、止盈赚 300，就是 1:3 的盈亏比。","body":["盈亏比由三个价格决定：入场价、止损价和止盈价。入场价到止损价的距离是风险，入场价到止盈价的距离是回报。下单前把这三个价格写清楚，就能算出这笔交易值不值得做。","盈亏比要和胜率一起看。盈亏比 1:3 时，只要胜率超过 25% 就能在不计手续费的情况下保本；盈亏比 1:1 时，胜率要超过 50%。高盈亏比的策略通常胜率较低，要能承受连续止损。",["盈亏比是计划，不是结果。止盈设在明显",["阻力位","support-and-resistance"],"之上，可能很难到达；临时把止损往后挪，会让原本的盈亏比失效。另外别忘了手续费、",["资金费","funding-rate"],"和",["滑点","slippage"],"会吃掉一部分回报。"]],"example":["假设你在 2,000 ",["USDT","usdt"]," 买入 ",["ETH","ethereum"],"，止损 1,900，止盈 2,300。每个 ETH 风险 100、回报 300，盈亏比 1:3，保本胜率是 1 ÷ (1 + 3) = 25%。如果十笔同样的交易只赢了 3 笔，结果是 3 × 300 − 7 × 100 = 200 USDT，仍然是盈利的。"],"mistakes":["为了让盈亏比好看，把止盈设在不现实的位置。","开仓后不断把止损往后移，实际亏损远大于计划风险。","只看盈亏比不看胜率，误以为高盈亏比就一定赚钱。"],"faq":[{"q":"盈亏比多少合适？","a":"没有固定答案，很多交易者把 1:2 以上作为参考门槛。关键是盈亏比和你策略的实际胜率匹配，长期期望值为正。"},{"q":"盈亏比怎么计算？","a":"用入场价到止损价的距离作为风险，入场价到止盈价的距离作为回报，两者相比即可。例如风险 50、回报 150，就是 1:3。"}],"title":"盈亏比是什么？风险回报比怎么算","description":"解释交易中的盈亏比（风险回报比）如何计算、它和胜率之间的关系，以及新手在设置止损和止盈时最容易犯的几个错误。","related":[["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["take-profit","止盈单（Take-Profit）","止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。"],["oco-order","OCO 订单（二选一订单）","OCO 订单（One-Cancels-the-Other）是把两笔订单绑定在一起，其中一笔成交后另一笔自动撤销，常用于同时设置止盈和止损。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"先想能亏多少，再决定买多少"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"zh-Hans","term":"期货合约（Futures Contract）","aka":["合约","期货","合约交易","futures"],"short":"期货合约是约定在未来以特定价格买入或卖出某种资产的标准化协议，在加密货币交易所中通常不交割实物币，而是用保证金结算盈亏。","body":[["币圈说的“合约”一般就是期货合约。你不需要真的持有 ",["BTC","bitcoin"],"，只要存入保证金，就能对 BTC 价格开多或开空：看涨开多，价格上涨赚钱；看跌开空，价格下跌赚钱。盈亏按合约价值和价格变动计算。"],["加密",["交易所","centralized-exchange"],"最常见的两类是",["永续合约","perpetual-futures"],"和",["交割合约","delivery-futures"],"：永续合约没有到期日，靠",["资金费率","funding-rate"],"贴近现货价格；交割合约有固定到期日，到期按交割价格结算。按保证金币种又分为 U 本位（",["USDT","usdt"]," 保证金）和币本位（以 BTC 等币作保证金）。"],"合约允许使用杠杆，同样的保证金可以控制更大的仓位，盈利和亏损都会被放大。当亏损让保证金低于维持保证金要求时，仓位会被强制平仓，也就是常说的爆仓。合约交易在部分国家和地区受限，交易所对不同地区用户开放的产品也不同。"],"example":"假设 BTC 价格 60,000 USDT，你开 0.1 BTC 的多单，合约价值 6,000 USDT，用 10 倍杠杆，需要约 600 USDT 保证金。价格涨到 63,000，盈利 0.1 × 3,000 = 300 USDT，相当于保证金的 50%。如果价格跌到 57,000，同样亏损 300 USDT，保证金只剩一半，继续下跌就会接近强平。","mistakes":["以为合约和现货一样“拿着不卖就不会亏完”，忽略合约会被强平。","把杠杆倍数当成收益倍数，没计算同等幅度下跌时的亏损。","分不清永续合约和交割合约，持有交割合约到期被自动结算。"],"faq":[{"q":"合约和现货有什么区别？","a":"现货是真正买入并持有币，最多亏到本金归零但不会被强平；合约是对价格涨跌的保证金交易，可以做空、可以加杠杆，亏损到一定程度会被强制平仓。"},{"q":"期货合约到期会怎样？","a":"交割合约到期时按交易所规定的交割价格结算盈亏，加密交易所通常是现金结算。永续合约没有到期日。"}],"title":"期货合约是什么？币圈合约交易入门","description":"解释加密货币期货合约（合约交易）的基本原理、永续合约与交割合约的区别、U本位与币本位，以及杠杆如何放大盈亏。","related":[["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["delivery-futures","交割合约（Delivery Futures）","交割合约是有固定到期日的期货合约，例如当周、次周、当季、次季合约，到期时按交割价格自动结算，不需要支付资金费率。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["margin-trading","杠杆交易（Margin Trading）","杠杆交易是用自己的资金作保证金，向交易所借入资金或币来放大买卖规模的交易方式，借款要付利息，亏损到一定程度会被强平。"],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"zh-Hans","term":"全仓保证金（Cross Margin）","aka":["全仓","全仓模式","cross margin"],"short":"全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。","body":[["在全仓模式下，仓位没有固定的保证金上限。只要账户里还有可用余额，亏损就会继续从余额里扣，",["强平价","liquidation-price"],"因此比同样",["杠杆","leverage"],"的逐仓更远。一个仓位的浮盈也可以给其他仓位当缓冲。"],"全仓的代价是风险不隔离：一笔判断错误的仓位可能把整个账户拖下水。很多人开了全仓以为“杠杆只有 3 倍”，却在亏损时不断用余额扛单，最后一次性爆仓。",["全仓适合做",["对冲","hedging"],"组合、或者能严格执行止损的交易者。部分",["交易所","centralized-exchange"],"的",["统一账户","unified-trading-account"],"或",["组合保证金模式","portfolio-margin"],"，是在全仓基础上进一步把现货、合约、期权放到一起计算风险，规则更复杂，使用前要看清楚说明。"]],"example":"假设账户有 10,000 USDT，你在全仓模式开一笔价值 50,000 USDT 的 BTC 多单，维持保证金率 0.5%，即 250 USDT。整个账户的 10,000 USDT 都能用来扛亏损，BTC 大约要跌 (10,000 − 250) ÷ 50,000 ≈ 19.5% 才会强平。如果改用逐仓只分配 5,000 USDT，跌约 9.5% 就会强平，但最多只亏 5,000 USDT。","mistakes":["以为全仓的强平价远就很安全，结果一次强平亏掉整个账户。","全仓模式下同时持有多个同方向的山寨币仓位，普跌时一起拖累保证金。","把准备用来补仓或提现的资金留在全仓账户里，被动成了保证金。"],"faq":[{"q":"全仓爆仓会亏掉所有钱吗？","a":"全仓模式下强平时，账户中用于全仓的可用余额都可能被用来弥补亏损，所以损失可能远大于单个逐仓仓位，通常会接近账户中全仓部分的全部资金。"},{"q":"全仓模式下多个仓位怎么算保证金？","a":"所有全仓仓位共享账户余额，盈利仓位的浮盈可以抵消亏损仓位，系统按整体权益和总维持保证金判断是否强平。"}],"title":"全仓是什么意思？全仓保证金模式与逐仓区别","description":"解释合约交易中全仓保证金模式的工作方式、为什么强平价更远但风险不隔离，以及什么样的交易者更适合使用全仓。","related":[["isolated-margin","逐仓保证金（Isolated Margin）","逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。"],["portfolio-margin","组合保证金（Portfolio Margin）","组合保证金是一种按整个投资组合的净风险计算保证金的模式，现货、合约、期权的仓位可以互相抵消风险，对冲良好的组合所需保证金更低。"],["unified-trading-account","统一账户（Unified trading account）","统一账户是交易所把现货、杠杆、合约和期权等交易放在同一个账户中的模式，账户里多种资产可以按折算率共同作为保证金，盈亏可以相互抵消。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"全仓：为什么一笔亏损会影响别的仓位？"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"zh-Hans","term":"做多与做空（Long and Short）","aka":["开多","开空","多单","空单"],"short":"做多是预期价格上涨而买入或开多单，价格上涨时盈利；做空是预期价格下跌而卖出或开空单，价格下跌时盈利，两者是交易的两个基本方向。","body":[["在现货市场，做多就是买币持有，最多亏到本金归零。在合约市场，你可以随时选择开多或开空，盈亏都按仓位数量乘以价格变化计算，再被",["杠杆","leverage"],"放大。"],["做多的最大亏损有限（价格最低到零），潜在收益理论上没有上限；做空正好相反，最大收益有限，价格上涨则亏损理论上没有上限。这就是为什么空单遇到暴涨时，",["强平","liquidation"],"和",["轧空","short-squeeze"],"会来得非常猛烈。"],[["合约交易","futures-contract"],"中的“多单”“空单”只是方向，不代表一定要先持有币。",["永续合约","perpetual-futures"],"在",["资金费率","funding-rate"],"为正时，多单要付资金费；为负时空单要付，所以同一个方向在不同时期的持仓成本也不同。"]],"example":"假设你在 3,000 USDT 开 2 ETH 的空单。如果 ETH 跌到 2,700，你盈利 (3,000 − 2,700) × 2 = 600 USDT；如果涨到 3,300，你亏损 600 USDT。换成多单，结果正好相反。同样是 10% 的价格变化，盈亏金额相同，但空单在价格持续上涨时没有自然的亏损上限，只能靠止损或强平终止。","mistakes":["以为做空比做多风险小，忽略空单亏损理论上无上限。","开仓时点错方向按钮，开多变开空。","只看方向判断对错，忽视持仓期间的资金费成本。"],"faq":[{"q":"做空是什么意思？","a":"做空是预期价格下跌而先卖出或开空单，价格下跌后再买回平仓，赚取差价。在合约里可以直接开空单，不需要先持有币。"},{"q":"做多和做空哪个风险大？","a":"做多最多亏到价格归零，做空在价格持续上涨时亏损理论上没有上限。实际风险更多取决于杠杆、仓位和止损。"}],"title":"做多和做空是什么意思？开多开空入门","description":"解释加密货币交易中做多和做空（开多、开空）的含义、各自的盈亏计算方式和风险特点，以及合约里多单空单的持仓成本。","related":[["short-selling","卖空（Short Selling）","卖空是先借入或通过合约卖出自己并不持有的资产，等价格下跌后再买回归还或平仓，从下跌中赚取差价的交易方式。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["long-short-ratio","多空比（Long/Short Ratio）","多空比是交易所统计的持有多单用户（或多单持仓）与持有空单用户（或空单持仓）之间的比例，用来观察散户或大户在某个合约上的情绪偏向。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"zh-Hans","term":"卖空（Short Selling）","aka":["做空","沽空","short selling"],"short":"卖空是先借入或通过合约卖出自己并不持有的资产，等价格下跌后再买回归还或平仓，从下跌中赚取差价的交易方式。","body":[["传统意义上的卖空，是先借入股票或币卖掉，日后买回还给出借人。在加密市场，你可以在",["现货杠杆","margin-trading"],"账户借币卖空，需要支付借币利息；更常见的是直接在合约市场开空单，不需要借币，持仓成本主要是",["资金费","funding-rate"],"。"],["卖空的风险结构和买入相反：最大收益是价格跌到零，亏损则随价格上涨不断扩大。被大量卖空的币，一旦开始上涨，空头的止损和",["强平","liquidation"],"会变成市价买单，推动价格进一步上涨，形成",["轧空","short-squeeze"],"。"],["卖空也常用于",["对冲","hedging"],"，比如持有现货的人开空单锁定价格，而不是单纯押注下跌。部分小币借不到币，或合约深度很差，卖空的执行成本会很高。"]],"example":["假设你在现货杠杆账户借入 10 个 SOL，在 150 ",["USDT","usdt"]," 卖出，得到 1,500 USDT。一周后 SOL 跌到 120，你花 1,200 USDT 买回 10 个 SOL 还给平台，赚 300 USDT，再扣除这一周的借币利息。如果 SOL 反而涨到 180，你需要花 1,800 USDT 买回，亏损 300 USDT 加利息。"],"mistakes":["以为卖空只要价格最终下跌就一定赚钱，忽略中途上涨可能先触发强平。","现货借币卖空时忘了利息在持续累积。","在资金费率深度为负的时候长期持有空单，付出大量资金费。"],"faq":[{"q":"没有币可以卖空吗？","a":"可以。在合约市场可以直接开空单，不需要持有币；在现货杠杆账户则由平台借币给你卖出。"},{"q":"卖空的风险在哪里？","a":"价格上涨时亏损没有理论上限，被大量做空的币还可能出现轧空，短时间内大幅上涨并引发连环强平。"}],"title":"卖空是什么？加密货币做空的方式与风险","description":"解释加密货币卖空（做空）的两种方式：现货杠杆借币卖出和合约开空单，用实例说明盈亏计算和轧空等主要风险。","related":[["long-and-short","做多与做空（Long and Short）","做多是预期价格上涨而买入或开多单，价格上涨时盈利；做空是预期价格下跌而卖出或开空单，价格下跌时盈利，两者是交易的两个基本方向。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["margin-trading","杠杆交易（Margin Trading）","杠杆交易是用自己的资金作保证金，向交易所借入资金或币来放大买卖规模的交易方式，借款要付利息，亏损到一定程度会被强平。"],["short-squeeze","轧空（Short Squeeze）","轧空是指价格上涨迫使大量空头止损或被强平，他们的平仓买单又进一步推高价格，形成连锁反应、价格在短时间内急速拉升的现象。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"zh-Hans","term":"基差（Futures Basis）","aka":["期现价差","升水","贴水","basis"],"short":"基差是期货合约价格与现货价格之间的差额，期货高于现货叫升水，低于现货叫贴水，到期时交割合约的基差会收敛到接近零。","body":[["基差 = 期货价格 − 现货价格（也有人反过来定义，看清楚即可）。在加密市场，",["季度合约","delivery-futures"],"在多头情绪浓厚时往往明显升水，反映资金成本和看涨需求；市场悲观时可能贴水。"],["为了比较不同到期日的合约，交易者常把基差折算成年化收益：基差百分比 × 365 ÷ 剩余天数。年化基差越高，",["期现套利","funding-rate-arbitrage"],"（买入现货、卖出期货、持有到期）的回报越高，所以基差也被当作衡量",["杠杆","leverage"],"需求的指标。"],[["永续合约","perpetual-futures"],"没有到期日，基差通过",["资金费率","funding-rate"],"来回归：永续价格高于指数时资金费为正。交割合约的基差则在到期时收敛。注意，到期前基差可能先扩大再收窄，提前平仓不一定能拿到全部基差。"]],"example":["假设 ",["BTC","bitcoin"]," 现货 60,000 USDT，60 天后到期的季度合约 61,500 USDT，基差 1,500，约为现货的 2.5%。折算年化约 2.5% × 365 ÷ 60 ≈ 15.2%。如果你买入 1 BTC 现货并卖出 1 BTC 季度合约持有到期，不论 BTC 涨跌，都能锁定约 1,500 USDT 的价差，再扣除手续费和资金占用成本。"],"mistakes":["把升水直接理解为市场对未来价格的预测。","只算基差收益，不计算手续费、保证金占用和合约空单被强平的风险。","以为基差一定是单调收敛的，提前平仓时遇到基差扩大造成亏损。"],"faq":[{"q":"基差为正说明什么？","a":"说明期货价格高于现货，即升水，通常反映市场做多需求较强、资金成本较高，但并不代表价格一定上涨。"},{"q":"年化基差怎么算？","a":"用基差除以现货价格得到百分比，再乘以 365 除以距离到期的天数，例如 2% 的基差、90 天到期，年化约 8.1%。"}],"title":"基差是什么？期货升水贴水与年化基差","description":"解释期货基差的定义、升水与贴水的含义、年化基差的计算方法，以及期现套利中基差到期收敛和中途扩大带来的风险。","related":[["delivery-futures","交割合约（Delivery Futures）","交割合约是有固定到期日的期货合约，例如当周、次周、当季、次季合约，到期时按交割价格自动结算，不需要支付资金费率。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["index-price","指数价格（Index Price）","指数价格是交易所根据多家主流现货交易所的价格，按一定权重加权计算出的综合现货价格，用作标记价格和资金费率的基准。"],["funding-rate-arbitrage","资金费率套利（Funding Rate Arbitrage）","资金费率套利是买入现货、同时在永续合约开等量空单，保持方向中性，赚取正资金费率期间空头收到的资金费的策略。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"zh-Hans","term":"充提币网络（链的选择）","aka":["充币网络","提币网络","转账网络","主网"],"short":"充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。","body":[["同一种币往往发行在多条链上。以 ",["USDT","usdt"]," 为例，常见网络有",["以太坊","ethereum"],"（ERC20）、波场（TRC20）、BNB 智能链（BEP20）、Solana、Arbitrum 等。它们名字相同，但分别存在于不同的账本里，彼此并不直接相通。"],["提币时",["交易所","centralized-exchange"],"会让你选网络，不同网络的手续费、到账速度和支持情况都不一样。以太坊主网的 ",["Gas 费","gas-fee"],"通常较高，波场和部分",["二层网络","layer-2"],"费用较低。手续费以页面实时显示为准，各交易所也会根据网络状况调整。"],"最关键的原则是：接收方充币页面显示的网络，必须和你提币时选的网络完全一致。选错网络，轻则需要人工找回并收费，重则资产永久丢失。"],"example":["假设你要把 1,000 USDT 从 A 交易所转到 B 交易所。A 交易所提现页面显示 ERC20 网络手续费约 3 USDT、TRC20 约 1 USDT。你先在 B 交易所确认它支持 TRC20 充值，再复制 B 的 TRC20 ",["充币地址","wallet-address"],"（T 开头），在 A 选择 TRC20 提现。最终到账 999 USDT，比走 ERC20 少付约 2 USDT 手续费。"],"mistakes":["只看币种名称，不看网络名称，把 BEP20 的 USDT 充到只支持 ERC20 的地址。","为了省手续费选择了接收方根本不支持的网络。","以为 0x 地址通用，就随便选一条 EVM 链发送。"],"faq":[{"q":"TRC20 和 ERC20 有什么区别？","a":"TRC20 是波场链上的代币标准，地址以 T 开头；ERC20 是以太坊链上的标准，地址以 0x 开头。两者手续费和到账速度不同，不能互相直接转账。"},{"q":"选错网络了怎么办？","a":"先查交易哈希确认币到了哪条链。如果收款地址在那条链上你能控制，可以切换网络找回；如果是交易所地址，联系对方客服申请找回，能否处理以及费用由平台决定。"}],"title":"充提币网络是什么？USDT 选 TRC20 还是 ERC20","description":"充提币时网络怎么选？讲清 TRC20、ERC20、BEP20 等网络的区别，为何收发双方必须同链，以及选错网络后的处理思路。","related":[["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["memo-tag","Memo / 标签（Destination Tag）","Memo（也叫标签、Tag）是部分区块链转账时附带的一段数字或文字，交易所靠它识别充值属于哪个用户，充值时漏填或填错就可能无法自动到账。"],["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"],["withdrawal-fee","提币手续费（Withdrawal fee）","提币手续费是你把加密资产从交易所转出到外部地址时，交易所收取的费用，通常按币种和网络收取固定数量，用于覆盖链上Gas费和平台的处理成本。"],["transaction-hash","交易哈希（TxID）","交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"zh-Hans","term":"内存池（Mempool）","aka":["交易池","Mempool","待确认交易池"],"short":"内存池是区块链节点用来暂存已广播但尚未被打包进区块的交易的等待区，交易在这里排队，矿工或验证者通常优先打包手续费更高的交易。","body":[["你发出一笔转账后，它不会立刻写进区块，而是先被广播到网络中的各个",["节点","node"],"，进入它们各自的内存池。矿工（",["工作量证明","proof-of-work"],"链）或",["验证者","validator"],"（",["权益证明","proof-of-stake"],"链）从内存池中挑选交易打包，区块空间有限时，出价更高的交易会更快被选中。"],["内存池的拥堵程度直接决定了手续费和等待时间。网络繁忙时，内存池里堆积大量待确认交易，Gas费或",["比特币","bitcoin"],"的手续费率会上涨；如果你给的费用太低，交易可能长时间卡住，甚至被节点丢弃。比特币支持RBF（用更高费用替换交易），",["以太坊","ethereum"],"钱包则可以用相同nonce发一笔更高Gas的交易来加速或取消。"],"内存池是公开的，这也带来MEV问题：机器人能看到你在DEX上的待成交大额交易，抢先下单或夹击你的交易（三明治攻击）。部分钱包提供私有交易通道来降低这类风险。"],"example":"假设你发送一笔比特币交易，大小为140 vB，设置手续费率5 sat/vB，总手续费700聪。此时内存池拥堵，被打包的交易费率大多在20 sat/vB以上，你的交易一直排不上。你用RBF把费率提高到25 sat/vB，总手续费变为3,500聪，多付了2,800聪（0.000028 BTC），交易在下一个区块被确认。","mistakes":["网络拥堵时设置过低的手续费，导致交易卡在内存池里很久。","交易卡住后反复重新发送新交易，结果后来几笔一起成交，重复付款。","在DEX上做大额交易时把滑点设得很宽，给内存池里的抢跑机器人留下空间。"],"faq":[{"q":"交易卡在内存池里怎么办？","a":"可以等网络不拥堵时自然被打包，也可以用钱包的加速功能提高手续费。比特币使用RBF或CPFP，以太坊用相同nonce发送更高Gas的替换交易。"},{"q":"内存池里的交易会过期吗？","a":"会。节点通常会在一段时间后或内存池满时丢弃低费率交易，丢弃后资金仍在原地址，你可以重新发送。"}],"title":"什么是内存池（Mempool）？交易为什么会卡住","description":"内存池是什么？了解交易广播后如何排队等待打包、手续费率如何影响确认速度，以及交易卡住时如何加速或替换。","related":[["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"],["transaction-hash","交易哈希（TxID）","交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。"],["mev","MEV（最大可提取价值）","MEV（最大可提取价值）是指区块生产者或搜索者通过调整、插入或排除区块中交易的顺序所能额外获得的利润，三明治攻击（夹子）是最常见的例子。"],["block-confirmations","区块确认数（Confirmations）","区块确认数是指一笔交易被打包进区块后，其后又新增了多少个区块，确认数越多，交易被回滚的可能性越小，交易所据此决定何时为你入账。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"显示成功却没到账，该查哪里？"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"zh-Hans","term":"免KYC交易所（No-KYC exchange）","aka":["无需KYC交易所","免实名交易所","No-KYC"],"short":"免KYC交易所是指不要求用户提交身份证件即可注册、交易或在一定额度内提币的交易平台，包括部分中心化交易所和链上去中心化交易所（DEX）。","body":[["免KYC大致有两类：一类是",["去中心化交易所","dex"],"，你用自己的钱包直接和",["智能合约","smart-contract"],"交互，本来就没有账户和实名环节；另一类是中心化平台允许未认证用户在一定额度内交易和提币，但保留随时要求认证的权利。"],["吸引人的地方在于注册快、隐私好。但代价也很明显：中心化的免KYC平台往往没有在你所在地区注册，出了纠纷很难追责；平台可能在风控触发或政策变化时突然要求补做KYC，未通过前资金被冻结；部分平台的",["流动性","liquidity"],"、",["提币手续费","withdrawal-fee"],"和安全记录也需要格外留意。"],["另外，免KYC不等于免监管或匿名：链上交易依然公开可查，你使用的",["法币通道","fiat-on-ramp"],"、充值来源仍会留下记录。是否可以使用这类平台，也取决于你所在国家的法律。"]],"example":["假设某平台允许未认证用户每天提币最多等值2 ",["BTC","bitcoin"],"。你在上面存入3 BTC交易，一段时间后账户增长到5 BTC。某天平台因风控升级，要求所有提币超过0.5 BTC的用户补做KYC，而你所在地区刚好不在它的服务范围内，认证无法通过。最终你只能每天提0.5 BTC，提完5 BTC需要10天，期间资金一直面临平台政策再次变化的风险。"],"mistakes":["以为免KYC就等于完全匿名，忽视了链上记录和充值来源可以被追溯。","把大额资金长期放在不需要认证、也没有监管注册的平台上。","不看用户协议中“平台有权随时要求认证”的条款。"],"faq":[{"q":"免KYC交易所合法吗？","a":"要看你所在地区的法律和平台是否在当地合规运营。有些地区要求服务商必须做KYC，未注册的平台可能在当地违规。"},{"q":"DEX算免KYC交易所吗？","a":"大多数DEX不需要注册账户，用户通过自己的钱包交易，所以通常被归入免KYC类别，但前端网站可能会限制某些地区访问。"}],"title":"什么是免KYC交易所？优缺点与潜在风险","description":"免KYC交易所是什么？了解不实名交易的两种形式、提币额度限制、突然要求补认证导致资金冻结的风险，以及合规问题。","related":[["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"],["withdrawal-fee","提币手续费（Withdrawal fee）","提币手续费是你把加密资产从交易所转出到外部地址时，交易所收取的费用，通常按币种和网络收取固定数量，用于覆盖链上Gas费和平台的处理成本。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC怎么做？证件应该交给谁？"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"zh-Hans","term":"法币入金通道（Fiat on-ramp）","aka":["法币入金","出入金","On-ramp","法币通道"],"short":"法币入金通道是把美元、欧元、人民币等法定货币换成加密资产的渠道，例如银行转账、银行卡快捷买币、第三方支付和P2P（C2C）交易。","body":[["大多数人进入加密市场的第一步就是入金。常见方式包括：向",["交易所","centralized-exchange"],"银行转账后在现货市场买币；用银行卡或第三方支付服务直接“快捷买币”；以及在P2P（",["C2C","p2p-trading"],"）市场向其他用户购买USDT。反过来把加密资产换回法币，叫出金（off-ramp）。"],"不同通道的成本差别很大。银行转账的手续费通常较低，但到账可能需要数小时到数天；银行卡快捷买币速度快，但手续费和汇率差往往更高；P2P价格由商家报价，可能高于或低于市场价，还要注意对方资金来源。","可用的入金方式取决于你所在国家、银行政策和平台的支付合作方。大部分正规入金通道都要求完成KYC。入金前先看清总成本，包括手续费、汇率差和最低金额，而不只看页面上显示的单一费率。"],"example":["假设你想用1,000美元买USDT。方案一：用银行卡快捷买币，页面显示手续费3%，扣除30美元后约得到970 ",["USDT","usdt"],"。方案二：通过银行转账入金到交易所，假设银行收取5美元手续费，到账995美元，再在现货市场以接近1:1的价格买入，扣除0.1%交易手续费后约得994 USDT。两者相差约24 USDT，代价是方案二要等一两个工作日到账。"],"mistakes":["只看标注的手续费，忽略汇率差和隐藏的价差成本。","通过非官方的“代充”渠道入金，资金来源不明导致银行卡或账户被冻结。","没完成KYC就先转账，导致资金无法入账、退款周期很长。"],"faq":[{"q":"哪种入金方式手续费最低？","a":"通常银行转账的总成本较低，银行卡快捷买币最方便但费用较高，具体要比较各平台在你所在地区的实际报价。"},{"q":"入金一定要做KYC吗？","a":"大多数正规的法币入金通道都要求实名认证，因为银行和支付机构需要满足反洗钱要求。"}],"title":"什么是法币入金通道？买币入金方式对比","description":"法币入金是什么？比较银行转账、银行卡快捷买币和P2P交易的速度与成本，学会计算入金总费用，避开代充等常见陷阱。","related":[["p2p-trading","P2P交易（C2C交易）","P2P交易（币圈常称C2C）是指用户之间在交易所提供的撮合平台上直接买卖加密资产，买方通过银行转账等方式付款给卖方，平台托管卖方的币作为担保。"],["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"第一次入金：钱从哪里来，进到哪里去？"},"coin":null,"tool":null,"cta":true}});
